import React from 'react';
import styles from './Table.module.css';

// CORREÇÃO: A tabela agora espera que 'headers' seja um array de objetos,
// cada um com uma 'key' (para aceder aos dados) e um 'label' (para exibir).
const Table = ({ headers, data }) => {
  return (
    <div className={styles.tableWrapper}>
      <table className={styles.table}>
        <thead>
          <tr>
            {headers.map((header) => <th key={header.key}>{header.label}</th>)}
          </tr>
        </thead>
        <tbody>
          {data.map((row) => (
            <tr key={row.id}>
              {headers.map(header => <td key={header.key}>{row[header.key]}</td>)}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default Table;
